Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>
  Representation
  <select id="representationStyle">
    <option>Space-filling</option>
    <option selected>Structural</option>
    <option>Ball-and-stick</option>
  </select>
</label>
<label>
  Move one H: H-C-H angle
  <input id="movableHydrogenAngle" type="range" min="70" max="130" step="0.5" value="109.5">
  <span><span id="angleValue">109.5</span>°</span>
</label>
<label style="flex-direction:row;align-items:center;gap:6px;">
