  Orbit molecule
</label>
<div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:4px;">
  <button id="prevStep">◀ Step</button>
  <button id="nextStep">Step ▶</button>
  <button id="playSteps">Play</button>
</div>
<div id="stepTitle" style="font-weight:bold;margin-top:5px;">Structural measurement</div>
<div id="stepNarration" style="line-height:1.35;color:#333;">
  The flat structural drawing labels the central carbon and four hydrogens while the magenta arc reads the H-C-H bond angle.
</div>
<div style="font-size:10px;color:#666;margin-top:4px;">C–H bond length remains 109 pm for every bond.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// lights → AmbientLight + DirectionalLight for glossy atom highlights
// tetrahedral atom positions → Vector3 directions scaled to C-H length 1.09
// space-filling carbon → SphereGeometry(0.70) dark gray, mostly hidden
// space-filling hydrogens → four SphereGeometry(0.55) warm off-white, overlapping
// ball-and-stick carbon → SphereGeometry(0.28) dark gray
// ball-and-stick hydrogens → four SphereGeometry(0.18) warm off-white
// ball-and-stick rods → four CylinderGeometry(radius 0.045) pale blue, aligned C-to-H
// structural bonds → Line segments in a front-facing local XY plane
// structural wedge → filled tapered triangular Mesh from C to lower/front H
// structural magenta extension rays → dashed Line objects along top and movable-left bonds
// structural magenta angle arc → sampled Line plus two V-shaped arrowheads
// structural bond-length guides → dashed horizontal Lines plus vertical double-headed arrow
// structural atom symbols and measurement text → addLabel HTML labels
// interactions → representation selector, angle slider, orbit checkbox, and step tween controls

scene.background = new THREE.Color(0xffffff);
document.getElementById('btnReset').style.display = '';

const methaneBondLength = 1.09;
const magenta = 0xff1493;
const carbonColor = 0x4b5555;
const hydrogenColor = 0xd9d8bd;
const rodColor = 0x9ec2df;

scene.add(new THREE.AmbientLight(0xffffff, 0.62));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.15);
keyLight.position.set(3.5, 4.5, 5);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.35);
fillLight.position.set(-4, 1.5, -2);
scene.add(fillLight);

const topDir = new THREE.Vector3(0, 1.03, -0.36).normalize();
const idealLeftDir = new THREE.Vector3(-0.89, -0.51, -0.36).normalize();
const rightDir = new THREE.Vector3(0.89, -0.51, -0.36).normalize();
const lowerDir = new THREE.Vector3(0, -0.25, 1.06).normalize();
const leftPlanePerp = idealLeftDir.clone().sub(topDir.clone().multiplyScalar(idealLeftDir.dot(topDir))).normalize();

function movableLeftDirFromAngle(angleDeg) {
  const a = THREE.MathUtils.degToRad(angleDeg);
  return topDir.clone().multiplyScalar(Math.cos(a)).add(leftPlanePerp.clone().multiplyScalar(Math.sin(a))).normalize();
}

let currentAngle = 109.5;

const atomPos = {
  top: topDir.clone().multiplyScalar(methaneBondLength),
  left: movableLeftDirFromAngle(currentAngle).multiplyScalar(methaneBondLength),
  right: rightDir.clone().multiplyScalar(methaneBondLength),
  lower: lowerDir.clone().multiplyScalar(methaneBondLength),
};

const spaceGroup = new THREE.Group();
const ballGroup = new THREE.Group();
const structuralGroup = new THREE.Group();
scene.add(spaceGroup, ballGroup, structuralGroup);

const cameraNormal = new THREE.Vector3(
  Math.cos(THREE.MathUtils.degToRad(45)) * Math.cos(THREE.MathUtils.degToRad(18)),
  Math.sin(THREE.MathUtils.degToRad(18)),
  Math.sin(THREE.MathUtils.degToRad(45)) * Math.cos(THREE.MathUtils.degToRad(18))
).normalize();
structuralGroup.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), cameraNormal);

const atomMaterialC = new THREE.MeshStandardMaterial({
  color: carbonColor,
  roughness: 0.34,
  metalness: 0.05,
});
const atomMaterialH = new THREE.MeshStandardMaterial({
  color: hydrogenColor,
  roughness: 0.22,
  metalness: 0.02,
});
const spaceCarbonMaterial = new THREE.MeshStandardMaterial({
  color: carbonColor,
  roughness: 0.38,
  metalness: 0.02,
});
const spaceHydrogenMaterial = new THREE.MeshStandardMaterial({
  color: hydrogenColor,
  roughness: 0.24,
  metalness: 0.02,
});
const rodMaterial = new THREE.MeshStandardMaterial({
  color: rodColor,
  roughness: 0.25,
  metalness: 0.08,
});
const blackLineMat = new THREE.LineBasicMaterial({ color: 0x111111 });
const magentaMat = new THREE.LineBasicMaterial({ color: magenta });
const magentaDashMat = new THREE.LineDashedMaterial({ color: magenta, dashSize: 0.08, gapSize: 0.045 });
const wedgeMat = new THREE.MeshBasicMaterial({ color: 0x050505, side: THREE.DoubleSide });

const sphereHi = 48;
const spaceCarbon = new THREE.Mesh(new THREE.SphereGeometry(0.70, sphereHi, sphereHi), spaceCarbonMaterial);
spaceGroup.add(spaceCarbon);

const spaceH = {};
for (const name of ['top', 'left', 'right', 'lower']) {
  const h = new THREE.Mesh(new THREE.SphereGeometry(0.55, sphereHi, sphereHi), spaceHydrogenMaterial);
  h.position.copy(atomPos[name]);
  spaceGroup.add(h);
  spaceH[name] = h;
}

const ballCarbon = new THREE.Mesh(new THREE.SphereGeometry(0.28, sphereHi, sphereHi), atomMaterialC);
ballGroup.add(ballCarbon);

const ballH = {};
const rods = {};
const yAxis = new THREE.Vector3(0, 1, 0);
function makeRod() {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 1, 28), rodMaterial);
  ballGroup.add(mesh);
  return mesh;
}
function alignRod(mesh, end) {
  const len = end.length();
  const mid = end.clone().multiplyScalar(0.5);
  mesh.position.copy(mid);
  mesh.scale.set(1, len, 1);
  mesh.quaternion.setFromUnitVectors(yAxis, end.clone().normalize());
}
for (const name of ['top', 'left', 'right', 'lower']) {
  const h = new THREE.Mesh(new THREE.SphereGeometry(0.18, sphereHi, sphereHi), atomMaterialH);
  h.position.copy(atomPos[name]);
  ballGroup.add(h);
  ballH[name] = h;
  rods[name] = makeRod();
  alignRod(rods[name], atomPos[name]);
}

function lineFromPoints(points, mat, parent = structuralGroup) {
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), mat);
  parent.add(line);
  if (mat.isLineDashedMaterial) line.computeLineDistances();
  return line;
}
function updateLine(line, points) {
  line.geometry.dispose();
  line.geometry = new THREE.BufferGeometry().setFromPoints(points);
  if (line.material.isLineDashedMaterial) line.computeLineDistances();
}
function localV(x, y, z = 0) {
  return new THREE.Vector3(x, y, z);
}
function worldFromLocal(x, y, z = 0) {
  return structuralGroup.localToWorld(localV(x, y, z));
}

const structural = {};
structural.top = localV(0, 1.09, 0);
structural.right = localV(0.95, -0.20, 0);
structural.lower = localV(0.25, -0.95, 0);
structural.left = localV(-0.99, -0.35, 0);

const bondTop = lineFromPoints([localV(0, 0), structural.top], blackLineMat);
const bondRight = lineFromPoints([localV(0, 0), structural.right], blackLineMat);
let bondLeft = lineFromPoints([localV(0, 0), structural.left], blackLineMat);

const wedgeGeom = new THREE.BufferGeometry();
const wedgeMesh = new THREE.Mesh(wedgeGeom, wedgeMat);
structuralGroup.add(wedgeMesh);

const extTop = lineFromPoints([localV(0, 1.19), localV(0, 1.75)], magentaDashMat);
let extLeft = lineFromPoints([localV(-1.05, -0.37), localV(-1.55, -0.55)], magentaDashMat);

const guideUpper = lineFromPoints([localV(0.15, 1.09), localV(1.42, 1.09)], magentaDashMat);
const guideLower = lineFromPoints([localV(0.15, 0), localV(1.42, 0)], magentaDashMat);
const lengthArrowLine = lineFromPoints([localV(1.32, 0), localV(1.32, 1.09)], magentaMat);
const lengthArrowHeadTop = lineFromPoints([], magentaMat);
const lengthArrowHeadBottom = lineFromPoints([], magentaMat);

const arcLine = lineFromPoints([], magentaMat);
const arcHeadStart = lineFromPoints([], magentaMat);
const arcHeadEnd = lineFromPoints([], magentaMat);

function arrowHeadPoints(point, tangent, size = 0.11, spread = 0.72) {
  const t = tangent.clone().normalize();
  const n = new THREE.Vector3(-t.y, t.x, 0).normalize();
  return [
    point.clone().add(t.clone().multiplyScalar(size)),
    point.clone(),
    point.clone().add(t.clone().multiplyScalar(size * Math.cos(spread))).add(n.clone().multiplyScalar(size * Math.sin(spread))),
    point.clone(),
    point.clone().add(t.clone().multiplyScalar(size * Math.cos(spread))).add(n.clone().multiplyScalar(-size * Math.sin(spread))),
  ];
}

function updateVerticalArrow() {
  updateLine(lengthArrowHeadTop, arrowHeadPoints(localV(1.32, 1.09), localV(0, -1), 0.10, 0.62));
  updateLine(lengthArrowHeadBottom, arrowHeadPoints(localV(1.32, 0), localV(0, 1), 0.10, 0.62));
}
updateVerticalArrow();

function setWedgeTowardLower() {
  const tip = structural.lower.clone();
  const base = localV(0, 0, 0);
  const dir = tip.clone().sub(base).normalize();
  const n = localV(-dir.y, dir.x, 0).normalize();
  const p1 = base.clone().add(n.clone().multiplyScalar(0.045));
  const p2 = base.clone().add(n.clone().multiplyScalar(-0.045));
  const p3 = tip.clone().add(n.clone().multiplyScalar(0.13));
  const p4 = tip.clone().add(n.clone().multiplyScalar(-0.13));
  wedgeGeom.setFromPoints([]);
  wedgeGeom.setAttribute('position', new THREE.Float32BufferAttribute([
    p1.x, p1.y, p1.z, p2.x, p2.y, p2.z, p3.x, p3.y, p3.z,
    p2.x, p2.y, p2.z, p4.x, p4.y, p4.z, p3.x, p3.y, p3.z,
  ], 3));
  wedgeGeom.computeVertexNormals();
}
setWedgeTowardLower();

function structuralLeftPosFromAngle(angleDeg) {
  const a = THREE.MathUtils.degToRad(angleDeg);
  const r = 1.05;
  return localV(-Math.sin(a) * r, Math.cos(a) * r, 0);
}

function updateArc(angleDeg) {
  const r = 0.78;
  const start = Math.PI / 2;
  const end = Math.PI / 2 + THREE.MathUtils.degToRad(angleDeg);
  const pts = [];
  const n = 54;
  for (let i = 0; i <= n; i++) {
    const t = start + (end - start) * (i / n);
    pts.push(localV(Math.cos(t) * r, Math.sin(t) * r));
  }
  updateLine(arcLine, pts);
  const pStart = pts[0];
  const pEnd = pts[pts.length - 1];
  const tanStartReverse = localV(Math.sin(start), -Math.cos(start), 0);
  const tanEndForward = localV(-Math.sin(end), Math.cos(end), 0);
  updateLine(arcHeadStart, arrowHeadPoints(pStart, tanStartReverse, 0.10, 0.70));
  updateLine(arcHeadEnd, arrowHeadPoints(pEnd, tanEndForward, 0.10, 0.70));
}

updateArc(currentAngle);

registerInteractive(ballGroup, {
  title: 'Ball-and-stick methane',
  tooltip: 'Click: four C-H bonds point toward a tetrahedron.',
  body: 'Carbon is the dark central atom. The four pale hydrogens sit 109 pm from carbon and are separated by the tetrahedral H-C-H angle, about 109.5°.'
});
registerInteractive(spaceGroup, {
  title: 'Space-filling methane',
  tooltip: 'Click: van der Waals spheres show occupied volume.',
  body: 'The large off-white hydrogen spheres overlap visually around carbon, so the dark carbon is mostly hidden between them.'
});
registerInteractive(structuralGroup, {
  title: 'Structural measurement drawing',
  tooltip: 'Click: magenta guides mark the tetrahedral measurements.',
  body: 'The magenta arc reads the H-C-H bond angle. The vertical double arrow marks the C-H bond length, fixed here at 109 pm.'
});

spaceGroup.visible = false;
ballGroup.visible = false;
structuralGroup.visible = true;

setCameraView({
  projection: 'perspective',
  azimuthDeg: 45,
  elevationDeg: 18,
  rollDeg: 0,
  heightFraction: 0.62
});

const structuralLabels = [];
function addStructuralLabel(html, x, y, opts = {}) {
  const label = addLabel(html, worldFromLocal(x, y, 0.01), opts);
  label.local = localV(x, y, 0.01);
  structuralLabels.push(label);
  return label;
}
