let stepIndex = 0;
let stepTween = null;

function setStepText(i) {
  document.getElementById('stepTitle').textContent = demoSteps[i].title;
  document.getElementById('stepNarration').textContent = demoSteps[i].narration;
}

function goToStep(i) {
  stepIndex = ((i % demoSteps.length) + demoSteps.length) % demoSteps.length;
  const step = demoSteps[stepIndex];
  setStepText(stepIndex);
  setRepresentation(step.state.representationStyle);

  const start = parseFloat(angleSlider.value);
  const end = step.state.movableHydrogenAngle;
  const t0 = performance.now();
  if (stepTween) cancelAnimationFrame(stepTween);
  function tick(now) {
    const u = Math.min(1, (now - t0) / 650);
    const eased = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    const val = start + (end - start) * eased;
    angleSlider.value = val.toFixed(1);
    updateAllForAngle(val);
    if (u < 1) stepTween = requestAnimationFrame(tick);
    else {
      angleSlider.value = end.toFixed(1);
      updateAllForAngle(end);
      stepTween = null;
    }
  }
  stepTween = requestAnimationFrame(tick);
}

