    pts.push(v(Math.cos(t) * radius, Math.sin(t) * radius, 0.012));
  }
  updateLine(arcLine, pts);

  const pTop = pts[0];
  const pLeft = pts[pts.length - 1];
  const tangentAtTop = v(-Math.sin(start), Math.cos(start), 0);
  const tangentAtLeftReverse = v(Math.sin(end), -Math.cos(end), 0);
  updateLine(arcHeadTop, arrowHead2D(pTop, tangentAtTop, 0.082, 0.60));
  updateLine(arcHeadLeft, arrowHead2D(pLeft, tangentAtLeftReverse, 0.082, 0.60));
