const allGroup = new THREE.Group();
const spaceGroup = new THREE.Group();
const structuralGroup = new THREE.Group();
const ballGroup = new THREE.Group();
scene.add(allGroup);
allGroup.add(spaceGroup, structuralGroup, ballGroup);

spaceGroup.position.set(-2.62, 0.02, 0);
structuralGroup.position.set(0, 0.02, 0);
structuralGroup.scale.setScalar(0.9);
ballGroup.position.set(2.62, 0.02, 0);

const spaceInner = new THREE.Group();
const ballInner = new THREE.Group();
spaceGroup.add(spaceInner);
ballGroup.add(ballInner);

const atomMaterialC = new THREE.MeshStandardMaterial({
  color: carbonColor,
  roughness: 0.34,
  metalness: 0.04
});
const atomMaterialH = new THREE.MeshStandardMaterial({
  color: hydrogenColor,
  roughness: 0.22,
  metalness: 0.02
});
const spaceCarbonMaterial = new THREE.MeshStandardMaterial({
  color: carbonColor,
  roughness: 0.42,
  metalness: 0.02
});
const spaceHydrogenMaterial = new THREE.MeshStandardMaterial({
  color: hydrogenColor,
  roughness: 0.25,
  metalness: 0.02
});
const rodMaterial = new THREE.MeshStandardMaterial({
  color: rodColor,
  roughness: 0.24,
  metalness: 0.08
});
const blackLineMat = new THREE.LineBasicMaterial({ color: 0x111111, depthTest: false });
const blackDashMat = new THREE.LineDashedMaterial({ color: 0x111111, dashSize: 0.045, gapSize: 0.035, depthTest: false });
const magentaMat = new THREE.LineBasicMaterial({ color: magenta, depthTest: false });
const magentaDashMat = new THREE.LineDashedMaterial({ color: magenta, dashSize: 0.055, gapSize: 0.038, depthTest: false });
const wedgeMat = new THREE.MeshBasicMaterial({ color: 0x050505, side: THREE.DoubleSide, depthTest: false });

function v(x, y, z = 0) {
  return new THREE.Vector3(x, y, z);
}

function lineFromPoints(points, mat, parent = structuralGroup) {
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), mat);
  line.renderOrder = 5;
  parent.add(line);
  if (mat.isLineDashedMaterial) line.computeLineDistances();
  return line;
}

function updateLine(line, points) {
  line.geometry.dispose();
  line.geometry = new THREE.BufferGeometry().setFromPoints(points);
  if (line.material.isLineDashedMaterial) line.computeLineDistances();
}

function makeSphere(radius, material, position, parent) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(radius, 64, 64), material);
  mesh.position.copy(position);
  parent.add(mesh);
  return mesh;
}

function alignCylinderBetween(mesh, start, end) {
  const delta = end.clone().sub(start);
  const len = delta.length();
  mesh.position.copy(start).add(end).multiplyScalar(0.5);
  mesh.scale.set(1, len, 1);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), delta.clone().normalize());
}

const tetra = {
  top: v(0.03, 0.98, -0.03).normalize(),
  left: v(-0.92, -0.31, 0.02).normalize(),
  right: v(0.91, -0.20, -0.23).normalize(),
  lower: v(0.12, -0.88, 0.46).normalize()
};

const modelPos = {};
for (const key of Object.keys(tetra)) {
  modelPos[key] = tetra[key].clone().multiplyScalar(methaneBondLength);
}

const spaceCarbon = makeSphere(0.60, spaceCarbonMaterial, v(0, 0, 0.01), spaceInner);
const spaceH = {};
const spaceBasePositions = {
  top: v(0.02, 0.49, -0.03),
  left: v(-0.48, -0.08, 0.08),
  right: v(0.49, -0.08, 0.13),
  lower: v(0.10, -0.43, 0.30)
};
for (const name of ['top', 'left', 'right', 'lower']) {
  spaceH[name] = makeSphere(0.49, spaceHydrogenMaterial, spaceBasePositions[name], spaceInner);
}
spaceInner.scale.setScalar(1.06);

const ballCarbon = makeSphere(0.25, atomMaterialC, v(0, 0, 0), ballInner);
const ballH = {};
const rods = {};
for (const name of ['top', 'left', 'right', 'lower']) {
  const rod = new THREE.Mesh(new THREE.CylinderGeometry(0.038, 0.038, 1, 28), rodMaterial);
  ballInner.add(rod);
  rods[name] = rod;
  alignCylinderBetween(rod, v(0, 0, 0), modelPos[name]);

  const h = makeSphere(0.17, atomMaterialH, modelPos[name], ballInner);
  ballH[name] = h;
}
ballInner.scale.setScalar(0.96);

const structural = {
  C: v(0, 0, 0.04),
  top: v(0, 0.72, 0.04),
  right: v(0.62, -0.20, 0.04),
  lower: v(0.34, -0.78, 0.08),
  left: v(-0.62, -0.35, 0.04)
};

const bondTop = lineFromPoints([v(0, 0.08, 0.03), structural.top.clone().add(v(0, -0.09, 0))], blackLineMat);
const bondLeft = lineFromPoints([v(-0.07, -0.03, 0.03), structural.left.clone().add(v(0.12, 0.07, 0))], blackLineMat);
const bondRightBack = lineFromPoints([v(0.08, -0.025, 0.03), structural.right.clone().add(v(-0.11, 0.035, 0))], blackDashMat);

const wedgeGeom = new THREE.BufferGeometry();
const wedgeMesh = new THREE.Mesh(wedgeGeom, wedgeMat);
wedgeMesh.renderOrder = 6;
structuralGroup.add(wedgeMesh);

const extTop = lineFromPoints([v(0, 0.84, 0.04), v(0, 1.42, 0.04)], magentaDashMat);
const extLeft = lineFromPoints([], magentaDashMat);
const guideTop = lineFromPoints([v(0.08, 0.72, 0.04), v(0.84, 0.72, 0.04)], magentaDashMat);
const guideBottom = lineFromPoints([v(0.66, -0.20, 0.04), v(0.84, -0.20, 0.04)], magentaDashMat);
const lengthArrow = lineFromPoints([v(0.75, -0.20, 0.04), v(0.75, 0.72, 0.04)], magentaMat);
const lengthArrowTop = lineFromPoints([], magentaMat);
const lengthArrowBottom = lineFromPoints([], magentaMat);
const arcLine = lineFromPoints([], magentaMat);
const arcHeadTop = lineFromPoints([], magentaMat);
const arcHeadLeft = lineFromPoints([], magentaMat);

function arrowHead2D(point, direction, size = 0.075, spread = 0.58) {
  const t = direction.clone().normalize();
  const n = v(-t.y, t.x, 0).normalize();
  return [
    point.clone().add(t.clone().multiplyScalar(size * Math.cos(spread))).add(n.clone().multiplyScalar(size * Math.sin(spread))),
    point.clone(),
    point.clone().add(t.clone().multiplyScalar(size * Math.cos(spread))).add(n.clone().multiplyScalar(-size * Math.sin(spread)))
  ];
}

function updateVerticalArrowHeads() {
  updateLine(lengthArrowTop, arrowHead2D(v(0.75, 0.72, 0.04), v(0, -1, 0), 0.08, 0.55));
  updateLine(lengthArrowBottom, arrowHead2D(v(0.75, -0.20, 0.04), v(0, 1, 0), 0.08, 0.55));
}
updateVerticalArrowHeads();

function updateWedge() {
  const base = v(0.11, -0.07, 0.07);
  const tip = structural.lower.clone();
  const dir = tip.clone().sub(base).normalize();
  const n = v(-dir.y, dir.x, 0).normalize();
  const b1 = base.clone().add(n.clone().multiplyScalar(0.028));
  const b2 = base.clone().add(n.clone().multiplyScalar(-0.028));
  const t1 = tip.clone().add(n.clone().multiplyScalar(0.116));
  const t2 = tip.clone().add(n.clone().multiplyScalar(-0.116));
  wedgeGeom.setAttribute('position', new THREE.Float32BufferAttribute([
    b1.x, b1.y, b1.z, b2.x, b2.y, b2.z, t1.x, t1.y, t1.z,
    b2.x, b2.y, b2.z, t2.x, t2.y, t2.z, t1.x, t1.y, t1.z
  ], 3));
  wedgeGeom.computeVertexNormals();
}
updateWedge();

function structuralLeftFromAngle(angleDeg) {
  const theta = THREE.MathUtils.degToRad(90 + angleDeg);
  return v(Math.cos(theta) * 0.71, Math.sin(theta) * 0.71, 0.04);
}

function updateArc(angleDeg) {
  const start = THREE.MathUtils.degToRad(90);
  const end = THREE.MathUtils.degToRad(90 + angleDeg);
  const radius = 1.00;
  const pts = [];
  const n = 76;
  for (let i = 0; i <= n; i++) {
    const t = start + (end - start) * (i / n);
    pts.push(v(Math.cos(t) * radius, Math.sin(t) * radius, 0.045));
  }
  updateLine(arcLine, pts);

  const pTop = pts[0];
  const pLeft = pts[pts.length - 1];
  const tangentAtTop = v(-Math.sin(start), Math.cos(start), 0);
  const tangentAtLeftReverse = v(Math.sin(end), -Math.cos(end), 0);
  updateLine(arcHeadTop, arrowHead2D(pTop, tangentAtTop, 0.082, 0.60));
  updateLine(arcHeadLeft, arrowHead2D(pLeft, tangentAtLeftReverse, 0.082, 0.60));
}

const structuralLabels = [];
function addStructuralLabel(html, pos, opts = {}) {
  const label = addLabel(html, structuralGroup.localToWorld(pos.clone()), opts);
  label.local = pos.clone();
  structuralLabels.push(label);
  return label;
}

setCameraView({
  projection: 'orthographic',
  azimuthDeg: 90,
  elevationDeg: 0,
  rollDeg: 0,
  target: [0, 0.06, 0],
  heightFraction: 0.60
});

const labelC = addStructuralLabel('C', v(0, 0, 0.11), { fontSize: '21px' });
const labelHTop = addStructuralLabel('H', structural.top.clone().add(v(0, 0.04, 0.08)), { fontSize: '21px' });
const labelHLeft = addStructuralLabel('H', structural.left.clone().add(v(-0.04, 0.02, 0.08)), { fontSize: '21px' });
const labelHRight = addStructuralLabel('H', structural.right.clone().add(v(0.08, -0.01, 0.08)), { fontSize: '21px' });
const labelHLower = addStructuralLabel('H', structural.lower.clone().add(v(0.05, -0.13, 0.08)), { fontSize: '21px' });
const angleReadoutLabel = addStructuralLabel('Bond<br>angle<br>109.5°', v(-1.48, 1.00, 0.08), { fontSize: '21px' });
const bondLengthLabel = addStructuralLabel('Bond<br>length<br>109 pm', v(1.22, 0.34, 0.08), { fontSize: '21px' });

function refreshStructuralLabels() {
  for (const label of structuralLabels) {
    label.pos.copy(structuralGroup.localToWorld(label.local.clone()));
  }
}

function updateStructuralForAngle(angleDeg) {
  structural.left.copy(structuralLeftFromAngle(angleDeg));
  updateLine(bondLeft, [v(-0.07, -0.03, 0.03), structural.left.clone().add(v(0.11, 0.06, 0))]);

  const leftDir = structural.left.clone().normalize();
  updateLine(extLeft, [
    structural.left.clone().add(leftDir.clone().multiplyScalar(-0.08)),
    structural.left.clone().add(leftDir.clone().multiplyScalar(0.46))
  ]);

  updateArc(angleDeg);

  labelHLeft.local.copy(structural.left.clone().add(v(-0.04, 0.02, 0.08)));
  const angleText = angleDeg.toFixed(1);
  angleReadoutLabel.div.innerHTML = `Bond<br>angle<br>${angleText}°`;
  document.getElementById('angleValue').textContent = angleText;
  refreshStructuralLabels();
}

function movableModelLeft(angleDeg) {
  const top = tetra.top.clone();
  const baseLeft = tetra.left.clone();
  const perp = baseLeft.sub(top.clone().multiplyScalar(baseLeft.dot(top))).normalize();
  const a = THREE.MathUtils.degToRad(angleDeg);
  return top.multiplyScalar(Math.cos(a)).add(perp.multiplyScalar(Math.sin(a))).normalize().multiplyScalar(methaneBondLength);
}

function updateModelsForAngle(angleDeg) {
  const left = movableModelLeft(angleDeg);
  modelPos.left.copy(left);
  ballH.left.position.copy(left);
  alignCylinderBetween(rods.left, v(0, 0, 0), left);
  spaceH.left.position.copy(spaceBasePositions.left.clone().add(v((angleDeg - 109.5) * -0.003, (angleDeg - 109.5) * 0.002, 0.01)));
}

function updateAllForAngle(angleDeg) {
  updateStructuralForAngle(angleDeg);
  updateModelsForAngle(angleDeg);
}

updateAllForAngle(109.5);

registerInteractive(spaceGroup, {
  title: 'Space-filling methane',
  tooltip: 'Space-filling model: atoms occupy volume.',
  body: 'The large van der Waals spheres overlap. The central carbon is visible only in the gaps between the four hydrogens arranged around it.'
});
registerInteractive(structuralGroup, {
  title: 'Structural formula',
  tooltip: 'Structural formula: wedge, dashed back-bond, and measurement guides.',
  body: 'The flat formula emphasizes connectivity. The solid wedge projects toward the viewer, while the dashed C–H bond recedes behind the page. The magenta arc marks the H–C–H angle.'
});
registerInteractive(ballGroup, {
  title: 'Ball-and-stick methane',
