  body: 'The rods make the tetrahedral shape visible: one hydrogen is upward, one left, one right/back, and one projects forward and downward. The ideal H–C–H angle is about 109.5°.'
});

function setLabelVisibility(list, visible) {
  for (const label of list) label.div.style.visibility = visible ? 'visible' : 'hidden';
}

function frameFor(style) {
  if (style === 'Space-filling') {
    setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, target: [-2.62, 0.02, 0], zoom: 2.0 });
  } else if (style === 'Structural') {
    setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, target: [0, 0.22, 0], zoom: 2.20 });
  } else if (style === 'Ball-and-stick') {
    setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, target: [2.62, 0.02, 0], zoom: 2.0 });
  } else {
    setCameraView({
      projection: 'orthographic',
      azimuthDeg: 90,
      elevationDeg: 0,
      rollDeg: 0,
      target: [0, 0.06, 0],
      heightFraction: 0.60
    });
  }
}

function setRepresentation(style, doFrame = true) {
  spaceGroup.visible = style === 'All three' || style === 'Space-filling';
  structuralGroup.visible = style === 'All three' || style === 'Structural';
  ballGroup.visible = style === 'All three' || style === 'Ball-and-stick';
  setLabelVisibility(structuralLabels, structuralGroup.visible);
  document.getElementById('representationStyle').value = style;
  if (doFrame) frameFor(style);
}

const styleSelect = document.getElementById('representationStyle');
const angleSlider = document.getElementById('movableHydrogenAngle');
const orbitBox = document.getElementById('orbitMolecule');

styleSelect.addEventListener('change', () => setRepresentation(styleSelect.value));
angleSlider.addEventListener('input', () => updateAllForAngle(parseFloat(angleSlider.value)));

controls.enableRotate = false;
controls.enablePan = true;
controls.enableZoom = true;

let orbitingModels = orbitBox.checked;
orbitBox.addEventListener('change', () => {
  orbitingModels = orbitBox.checked;
});

let lastSpin = performance.now();
function spinModels(now) {
  requestAnimationFrame(spinModels);
  const dt = Math.min(0.04, (now - lastSpin) / 1000);
  lastSpin = now;
  if (orbitingModels) {
    spaceInner.rotation.y += dt * 0.45;
    ballInner.rotation.y += dt * 0.62;
  }
}
requestAnimationFrame(spinModels);

const demoSteps = [
  {
    title: 'Three representations of methane',
    narration: 'The space-filling, structural, and ball-and-stick drawings are shown side by side, matching the textbook comparison.',
    state: { representationStyle: 'All three', movableHydrogenAngle: 109.5 }
  },
  {
    title: 'Structural measurement',
    narration: 'The structural formula is deliberately flat and front-on. The magenta arc reads the H-C-H bond angle, and the double arrow marks the 109 pm C-H bond length.',
    state: { representationStyle: 'Structural', movableHydrogenAngle: 109.5 }
  },
  {
    title: 'Connectivity view',
    narration: 'The ball-and-stick model keeps all four hydrogens visible: top, left, right/back, and forward/down.',
    state: { representationStyle: 'Ball-and-stick', movableHydrogenAngle: 109.5 }
  },
  {
    title: 'Occupied-volume view',
    narration: 'The space-filling model emphasizes the volume occupied by the atoms; the hydrogens overlap and partly hide the central carbon.',
    state: { representationStyle: 'Space-filling', movableHydrogenAngle: 109.5 }
  },
  {
    title: 'Distort one H-C-H angle',
    narration: 'Move one hydrogen away from the ideal tetrahedral value. The structural arc and the model both update while the C-H bond length remains fixed.',
    state: { representationStyle: 'All three', movableHydrogenAngle: 86 }
  }
];

let stepIndex = 0;
let stepTween = null;
let playing = false;
let playTimer = null;

function setStepText(i) {
  document.getElementById('stepTitle').textContent = demoSteps[i].title;
  document.getElementById('stepNarration').textContent = demoSteps[i].narration;
}

function goToStep(i) {
  stepIndex = ((i % demoSteps.length) + demoSteps.length) % demoSteps.length;
  const step = demoSteps[stepIndex];
  setStepText(stepIndex);
  setRepresentation(step.state.representationStyle);

  const start = parseFloat(angleSlider.value);
  const end = step.state.movableHydrogenAngle;
  const t0 = performance.now();
  if (stepTween) cancelAnimationFrame(stepTween);

  function tick(now) {
    const u = Math.min(1, (now - t0) / 620);
    const eased = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    const val = start + (end - start) * eased;
    angleSlider.value = val.toFixed(1);
    updateAllForAngle(val);
    if (u < 1) {
      stepTween = requestAnimationFrame(tick);
    } else {
      angleSlider.value = end.toFixed(1);
      updateAllForAngle(end);
      stepTween = null;
    }
  }
  stepTween = requestAnimationFrame(tick);
}

document.getElementById('prevStep').addEventListener('click', () => goToStep(stepIndex - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(stepIndex + 1));
document.getElementById('playSteps').addEventListener('click', () => {
  playing = !playing;
  document.getElementById('playSteps').textContent = playing ? 'Pause' : 'Play';
  if (!playing) {
    clearInterval(playTimer);
    return;
  }
  goToStep(stepIndex);
  playTimer = setInterval(() => {
    if (playing) goToStep(stepIndex + 1);
  }, 3800);
});

setStepText(0);
setRepresentation('All three', false);
refreshStructuralLabels();
